/**
 * @file
 * Merges retained operations without replacing a live Projection's independent history.
 */
#include "../class.hpp"

namespace sequencer {
Result Projection::merge(const Gossip &insertions, const std::vector<Acknowledgement> &frontiers) {
  auto result = apply(insertions);
  // Retained claims are observed after Acknowledgements generated by apply, matching snapshot
  // application order.
  for (const auto &a : frontiers)
    frontier.observe(a);
  return result;
}
} // namespace sequencer
